     * @param infos
     * @param maxNumSegments
     * @return
     * @throws IOException
     */
    private OneMerge findOneSegmentToExpunge(final SegmentInfos infos, final int maxNumSegments) throws IOException
    {
        int expungeCandidate = -1;
        int maxDelCount = 0;

        for (int i = maxNumSegments - 1; i >= 0; i--)
        {
            final SegmentInfoPerCommit info = infos.info(i);
            final int delCount = info.getDelCount();
            if (delCount > maxDelCount)
            {
                expungeCandidate = i;
                maxDelCount = delCount;
            }
        }

        if (maxDelCount > 0)
        {
            return new OneMerge(Collections.singletonList(infos.info(expungeCandidate)));
        }

        return null;
    }

    /**
     * 
     * 
     * @param sizes
     * @param bestSegSize
     * @return
     */
    private int[] findSmallestOneMerge(final long[] sizes, final long bestSegSize)
    {
        long targetSize = -1;
        int targetIndex = -1;
        final int n = sizes.length;

        final int skip = 0; // 

        // 
        for (int i = n - skip - 1; i >= 0; i--) // 
        {
            final long size1 = sizes[i];
            if (size1 < bestSegSize) // 
            {
                if (-1 == targetSize || size1 < targetSize)
                {
                    targetSize = size1;
                    targetIndex = i;
                }
            }
        }

        if (-1 != targetIndex)
        {
            for (int j = n - skip - 1; j >= 0; j--)//
            {
                if (targetIndex != j)
                {
                    final long size2 = sizes[j];

                    if (targetSize + size2 <= bestSegSize) // 
                    {
                        return new int[]
                        { targetIndex, j };
                    }
                }
            }
        }

        return null;
    }

